 924		% Source: references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:936-941,
 925		% the same-placement comparison preceding eq:pasting-q1.
 926		This formalization-only auxiliary isolates the same-placement comparison
 927		used for the first pasting hypothesis in the proof of
 928		Lemma~\ref{lem:qld-xz-lines}.
 929		There is a universal constant $C\geq1$ such that, for every admissible
 930		parameter set, projective strategy of success at least $1-\eps$,
 931		directed opposite-placement pair $(p_1,p_2)$, and $W\in\{X,Z\}$,
 932		\[
 933			\E_{(\ell,u)\sim D_{\mathsf{Line}}}
 934			\sum_{a\in\F_q\cup\{\bot\}}
 935			\left\|\left(
 936			(\hat M^{(\mathrm{Line},W),\ell}_{[\mathrm{eval}_u(\cdot)=a]})_{p_2}
 937			-(\hat M^{(\mathrm{Point},W),u}_a)_{p_2}
 938			\right)\ket{\hat\psi}\right\|^2
 939			\leq C\bigl(\eps+\delta_{\mathrm{Line}}(\eps)\bigr),
 940			\qquad \delta_{\mathrm{Line}}(\eps)=\sqrt{\eps}.
 941		\]
 942		Here $D_{\mathsf{Line}}$ is the equal mixture of the seed-bearing axis
 943		and diagonal laws of Definition~\ref{def:line-point-dist}, not a uniform
 944		law on geometric lines. Evaluation is completed by the residual outcome
 945		$\bot$ of Definition~\ref{def:ideg-deg-polynomials}, while
 946		$\hat M^{(\mathrm{Point},W),u}_{\bot}=0$.
 947	\end{theorem}
 948	\begin{proof}
 949		\leanok
 950		\uses{lem:qld-comm-line-cons, lem:qld-comm-cons, lem:alnf, lem:dlnf,
 951			prop:triangle-inequality-for-approx_delta}
 952		Item~3 of Lemma~\ref{lem:qld-comm-line-cons} compares the evaluated
 953		line measurement on $p_2$ with the completed point measurement on
 954		$p_1$, at cost $C_{\mathrm{Line}}\delta_{\mathrm{Line}}(\eps)$.
 955		Point self-consistency compares the latter with the point measurement
 956		on $p_2$, at cost $C_{\mathrm{Point}}\eps$: the point marginal of
 957		$D_{\mathsf{Line}}$ is uniform by Lemmas~\ref{lem:alnf}
 958		and~\ref{lem:dlnf}, and adjoining a zero effect does not change the
 959		distance. The squared triangle inequality proves the assertion with
